#!/usr/bin/env python3
# © Mayanktaker Computers & Web Development | https://mayanktaker.com
"""Pure Tela name-parity mapping: every Tela icon name resolves to a glyph in this pack.

Name coverage, not artwork parity: a missing Tela name maps to the best
token-matched catalog glyph, or to a context-appropriate generic for the tail.
This module is pure data + pure functions (no filesystem access); Task 8 emits
the symlinks from PARITY_ALIASES. Refresh the generated block with:

    python3 tools/dev/snapshot_tela_names.py --catalog
    python3 tools/dev/snapshot_tela_names.py /path/to/Tela-circle

Note: the brief's devices plain generic `computer` does not exist in the
catalog, so the nearest verified plain device glyph `network` is used instead.
"""

import re

CATALOG_PACK_NAME = "MT-Nordic-Blue-Icons"
STRIP_SUFFIXES = ("-symbolic", "-app", "-panel", "-gui", "-icon", "-desktop")
STOPWORDS = frozenset({"org", "kde", "gnome", "the", "app", "com"})
MIN_TOKEN_MATCH = 1
DEFAULT_CONTEXT = "apps"
# Contexts the built suites declare; parity links only ever land in these.
DECLARED_CONTEXTS = frozenset({"apps", "actions", "status", "places", "devices", "mimetypes", "ui", "categories"})
# Tela contexts with no declared equivalent, normalized to the nearest declared one.
CONTEXT_NORMALIZATION = {"panel": "status", "emblems": "actions", "emotes": "actions", "animations": "status"}
PRIMARY_CONTEXT_ORDER = (
    "apps",
    "places",
    "mimetypes",
    "devices",
    "status",
    "actions",
    "panel",
    "categories",
    "emblems",
    "emotes",
    "animations",
    "symbolic",
)
CONTEXT_GENERICS = {
    "apps": ("applications-symbolic", "application-x-generic"),
    "places": ("folder-symbolic", "folder"),
    "status": ("dialog-information-symbolic", "application-x-generic"),
    "actions": ("dialog-information-symbolic", "application-x-generic"),
    "panel": ("dialog-information-symbolic", "application-x-generic"),
    "mimetypes": ("document-open-symbolic", "application-x-generic"),
    "devices": ("network-symbolic", "network"),
    "categories": ("dialog-information-symbolic", "preferences-system"),
}

_SUFFIX_RE = re.compile(r"(?:-(?:" + "|".join(s[1:] for s in STRIP_SUFFIXES) + r"))+$")
_TOKEN_RE = re.compile(r"[^a-z0-9]+")
_TOKEN_CACHE: dict[str, tuple[str, ...]] = {}
_INDEX_MEMO: tuple[set[str], dict[str, object]] | None = None


def parity_tokens(name: str) -> tuple[str, ...]:
    # Lowercase, drop strip-suffixes, stopwords (incl. the com TLD) and pure-digit noise tokens.
    if name in _TOKEN_CACHE:
        return _TOKEN_CACHE[name]
    base = _SUFFIX_RE.sub("", name.lower())
    tokens = tuple(t for t in _TOKEN_RE.split(base) if t and t not in STOPWORDS and not t.isdigit())
    _TOKEN_CACHE[name] = tokens
    return tokens


def primary_context(contexts: list[str]) -> str:
    # Deterministic primary context: known order first, then lexicographic for unknowns.
    for context in PRIMARY_CONTEXT_ORDER:
        if context in contexts:
            return context
    return min(contexts)


def _candidate_index(catalog: set[str]) -> dict[str, object]:
    # Memoized inverted index: candidate token counts plus per-symbolicness token -> candidates.
    global _INDEX_MEMO
    if _INDEX_MEMO is not None and _INDEX_MEMO[0] == catalog:
        return _INDEX_MEMO[1]
    tokens_by_candidate = {candidate: parity_tokens(candidate) for candidate in catalog}
    lengths = {candidate: len(tokens) for candidate, tokens in tokens_by_candidate.items()}
    tokmap: dict[bool, dict[str, set[str]]] = {True: {}, False: {}}
    for candidate, tokens in tokens_by_candidate.items():
        bucket = tokmap[candidate.endswith("-symbolic")]
        for token in tokens:
            bucket.setdefault(token, set()).add(candidate)
    index = {"lengths": lengths, "tokmap": tokmap}
    _INDEX_MEMO = (set(catalog), index)
    return index


def _best_match(name: str, catalog: set[str]) -> str | None:
    # Highest token overlap within the requesting symbolicness; ties: token-count delta, then name.
    want_symbolic = name.endswith("-symbolic")
    tokens = set(parity_tokens(name))
    if not tokens:
        return None
    index = _candidate_index(catalog)
    bucket: dict[str, set[str]] = index["tokmap"][want_symbolic]  # type: ignore[index]
    scores: dict[str, int] = {}
    for token in tokens:
        for candidate in bucket.get(token, ()):
            scores[candidate] = scores.get(candidate, 0) + 1
    best_key: tuple[int, int, str] | None = None
    best: str | None = None
    for candidate, score in scores.items():
        if score < MIN_TOKEN_MATCH:
            continue
        lengths: dict[str, int] = index["lengths"]  # type: ignore[index]
        key = (-score, abs(lengths[candidate] - len(tokens)), candidate)
        if best_key is None or key < best_key:
            best_key, best = key, candidate
    return best


def _generic(context: str | None, symbolic: bool) -> str:
    # Context generic honoring the request's symbolicness (unknown contexts fall back to apps).
    symbolic_generic, plain_generic = CONTEXT_GENERICS.get(context or DEFAULT_CONTEXT, CONTEXT_GENERICS[DEFAULT_CONTEXT])
    return symbolic_generic if symbolic else plain_generic


def classify_parity(name: str, catalog: set[str]) -> str:
    # "present" (in catalog), "matched" (token match >= threshold), or "generic" (context fallback).
    if name in catalog:
        return "present"
    if _best_match(name, catalog) is None:
        return "generic"
    return "matched"


def map_parity_name(name: str, catalog: set[str], context: str | None = None) -> str:
    # Pure deterministic resolver: exact name, then best token match, then context generic.
    if name in catalog:
        return name
    best = _best_match(name, catalog)
    if best is not None:
        return best
    return _generic(context, name.endswith("-symbolic"))


def emission_contexts(raw_contexts: list[str]) -> list[str]:
    # Snapshot contexts normalized to declared ones, deduped in order; apps when nothing survives.
    out: list[str] = []
    for raw in raw_contexts:
        ctx = CONTEXT_NORMALIZATION.get(raw, raw)
        if ctx in DECLARED_CONTEXTS and ctx not in out:
            out.append(ctx)
    return out or [DEFAULT_CONTEXT]


